from __future__ import absolute_import
import logging


class RemoteIOError(IOError):
    def __init__(self, path, ip):
        super(RemoteIOError, self).__init__(
            "Path {} not exists on host with ip {}".format(path, ip))


class ConnectionParametersError(AttributeError):
    def __init__(self, *args):
        super(ConnectionParametersError, self).__init__(*args)


class ParsingError(Exception):
    def __init__(self, exception):
        super(ParsingError, self).__init__(
            "Couldn't parse file content because of {}: {}".format(
                exception.__class__.__name__, str(exception)))
        logging.exception(exception)


class MissingCellsMapContent(Exception):
    def __init__(self, msg):
        super(MissingCellsMapContent, self).__init__(msg)


class MissingSWBuildBranch(RuntimeError):
    pass


class MissingSemName(RuntimeError):
    pass
